head.script:
// DOM 조회 순서(받은 id → mf_ 접두사 → G_ 뒤 접두사 → 접두사 제거). 2026-11
scwin.__getDom = function(id) {
    var P = 'mf_', d = function(k) { return document.getElementById(k); }, dd = function(k) { return k.replace(/(mf_){2,}/g, P); };
    var r = d(id); if (r) return r;
    var s = dd(P + id); r = d(s); if (r) return r;
    var g = s.indexOf('G_');
    if (g >= 0) { s = dd(s.slice(0, g + 2) + P + s.slice(g + 2)); r = d(s); if (r) return r; s = dd(P + s); r = d(s); if (r) return r; }
    return d(s.replace(P, ''));
};
// jQuery 조회 순서(받은 선택자 → 없으면 mf_ 접두사). 2026-11
scwin.__getJq = function(q) {
    var j = $(q); if (j.length) return j;
    var P = 'mf_', t = q.trim(), r = t.slice(1);
    if (r.slice(0, 2) === 'G_') r = 'G_' + P + r.slice(2); else if (r.slice(0, P.length) !== P) r = P + r;
    return $(t.slice(0, 1) + r);
};
scwin.onpageload = function() {
	dlTmpList1.setJSON([{ "col101": "링크", "col102": "1", "col103": "버튼", "col104": "", "col105": "1", "col106": "02", "col107": "20190116", "col108": "테스트 입니다.", "col109": "테스트", "col110": "02 03", "col111": "123", "col112": "01" }]);
	dlTmpList1.insertRow(1);
	dlTmpList1.insertRow(2);
};
scwin.dynamicSubmission = function(option, req) {
    var submissionObj = option;
    $p.createSubmission(submissionObj);
    $p.executeSubmission("submission2", req);
};
scwin.gridView1_onbeforeedit = function(row, col, value) {
	if (col == 5 || col == 6) {
		var reqData = {
			"CommonData": { appCd: "DOC", chk1: "N", chk2: "N", chk3: "N", mnuNo: "0000002939", pgmNo: "", screenId: "UIDOC0042?uiMode=C", searchId: "", tjUrl: "/UDOC0042/searchPolCdList.do?locale=ko" },
			"dmSearchLoop": { "svcLoopCd": "PS2", "skdDirCd": "W" }
		};
		var subOpt = {
			id: "submission2",
			target: "data:json,{'id':'dlPopCobList2','key':'dlPopCobList'}",
			mode: "asyncronous",
			action: "/data/gridView_submission_selectbox_WEFF-772_(WSQ-4113).json",
			method: "post",
			mediatype: "application/json",
			encoding: "UTF-8"
		};
		scwin.dynamicSubmission(subOpt, reqData);
	}
};
scwin.checkVal1 = function() {
    var select_width = scwin.__getJq(scwin.__getDom($p.id + 'gridView1_cell_1_5')).width();
    var select_table_width = parseInt(scwin.__getDom('G_'+$p.id+'gridView1___selectbox_col106_itemTable').style.width) + 5;
    return select_table_width > select_width
}
scwin.checkVal2 = function() {
    var select_width = scwin.__getJq(scwin.__getDom($p.id + 'gridView1_cell_1_5')).width();
    var select_table_width = parseInt(scwin.__getDom('G_'+$p.id+'gridView1___autoComplete_1_col112_col112_itemTable').style.width) + 5;
    return select_table_width > select_width
}
